-- FK-safe idempotent reset (children before parents):
DELETE FROM coach_purchase_items;
DELETE FROM coach_transactions;
DELETE FROM coach_odp_profiles;
DELETE FROM coach_catalog;
DELETE FROM meta_attribute_catalog;

